          return '<div class="col"><div style="display:flex;justify-content:space-between;font-size:13px;padding:2px 4px 4px;gap:6px"><span><i style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' + st[2] + ';margin-right:6px"></i>' + st[0] + ' <span class="t-dim">· ' + st[1] + '%</span></span><span class="t-dim tab">' + (s ? Math.round(s / 1000) + ' tys.' : '') + '</span></div>' +
            ls.map(function (l) { var demo = l.id === DEAL_ID; return '<button class="lead" data-act="lead" data-id="' + l.id + '"' + (demo ? ' style="border-color:rgba(136,255,88,.5)"' : '') + '><b style="font-size:14px;display:block">' + l.title + '</b><small class="t-muted">' + l.client + '</small><span style="display:flex;justify-content:space-between;align-items:center;margin-top:10px"><b>' + l.value + '</b><span class="chip">' + l.source + '</span></span>' + pushLine(l) + '' + (demo ? '<span class="chip c-green" style="margin-top:8px">pełna ścieżka demo</span>' : '') + '</button>'; }).join('') + '</div>';
