      '<div><div class="eyebrow" style="margin:8px 0 6px">Rejestr komentarzy i zatwierdzeń · ' + d.cm.length + '</div><div class="list">' + (d.cm.length ? d.cm.map(function (c) { return '<div class="row" style="justify-content:flex-start;align-items:flex-start"><small class="t-dim tab" style="flex:none;width:84px">' + c.d + '</small><span style="flex:1;min-width:0;font-size:14px">' + esc(c.t) + '<br><small class="t-dim">' + esc(c.who) + (c.v ? ' · ' + c.v : '') + '</small></span></div>'; }).join('') : '<p class="t-dim" style="margin:6px 0">Brak wpisów.</p>') + '</div></div><button class="btn full" data-act="close">Zamknij</button>';
