      '<div class="grid g2"><section class="card"><h2 style="font-size:17px;margin-bottom:8px">Gdzie wykryto błąd</h2>' + ['Double check', 'Review produkcyjny', 'Produkcja', 'Montaż', 'Klient'].map(function (s) { var n = st[s] || 0, k = DERR.filter(function (e) { return e.at === s; }).reduce(function (a, e) { return a + e.cost; }, 0); return '<div class="row"><span>' + s + '<br><small class="t-dim">' + (k ? 'koszt ' + zl(k) : s === 'Double check' || s === 'Review produkcyjny' ? 'bez kosztu poprawki' : '—') + '</small></span><b class="tab ' + (s === 'Double check' || s === 'Review produkcyjny' ? 't-green' : 't-red') + '" style="align-self:center">' + n + '</b></div>'; }).join('') + '</section>' +
      '<section class="card"><div class="h-row" style="margin:0 0 8px"><h2 style="font-size:17px">Rejestr błędów</h2><button class="btn" style="min-height:34px;font-size:12px" data-act="dkerrai">' + I.spark + 'Agent: analiza</button></div><div class="list">' + DERR.slice().sort(function (a, b) { return dParse(b.d) - dParse(a.d); }).map(function (e) { return '<div class="row" style="align-items:flex-start"><span style="min-width:0"><b class="num t-pink">' + e.nr + '</b> ' + esc(e.t) + '<br><small class="t-dim">' + e.d + ' · ' + esc(e.c) + ' · ' + esc(e.who) + ' · poprawka ' + e.v + '</small></span><span style="text-align:right;flex:none"><span class="chip ' + (e.cost ? 'c-red' : 'c-green') + '">' + e.at + '</span><br><small class="tab ' + (e.cost ? 't-red' : 't-green') + '">' + (e.cost ? zl(e.cost) : 'oszcz. ' + zl(e.sv)) + '</small></span></div>'; }).join('') + '</div>' + (pv.errAi ? '<div class="alert a-green" style="flex-direction:column;align-items:flex-start;gap:4px;margin-top:8px"><b class="t-green">Agent kontroli dokumentacji</b>' + pv.errAi + '<small class="t-dim">Tryb demo – wnioski policzone z rejestru błędów.</small></div>' : '') + '</section></div>';
