      if (act === 'reserve') { p.st.reserved = true; p.st.hist = p.st.hist || []; p.st.hist.unshift([today(), 'Zarezerwowano materiały w Wapro, braki zamówione u dostawców.']); saveProj(); render(); toast('Rezerwacja w Wapro Mag (iMag API) – ok'); }
