  function carStart() { clearInterval(CAR.timer); CAR.timer = setInterval(function () { if (!$('#botPanel')) return clearInterval(CAR.timer); carGo(CAR.i + 1); }, (CARCFG.speed || 4.5) * 1000); var tr = $('#botCarTrack'); if (tr) tr.addEventListener('scroll', function () { var k = Math.round(tr.scrollLeft / Math.max(1, tr.clientWidth)); if (k !== CAR.i) { CAR.i = k; $$('#botCar [data-act="carto"]').forEach(function (d, j) { d.style.width = (j === k ? 16 : 6) + 'px'; d.style.background = j === k ? 'var(--pink)' : 'rgba(255,255,255,.3)'; }); } }, { passive: true }); }

