  function rcpSetOn(act, el) {
    var sc = window.scrollY, re = function () { render(); window.scrollTo(0, sc); };
    if (act === 'rcpprov') { RCPCFG.provider = el.dataset.v; saveRcp(); re(); return true; }
    if (act === 'rcpon') { var r = RCPCFG.readers[+el.dataset.i]; r.on = !r.on; saveRcp(); re(); return true; }
    if (act === 'rcpauto') { RCPCFG.autoclose = !RCPCFG.autoclose; saveRcp(); re(); return true; }
    if (act === 'rcptest') { toast(RCPCFG.key ? 'Test: wysłano zapytanie do ' + RCPCFG.endpoint : 'Tryb demo – wpisz endpoint i token, aby połączyć się z systemem RCP'); return true; }
    return false;
  }
