          '<circle cx="' + j.x + '" cy="' + j.y + '" r="26" fill="rgba(136,255,88,.22)"/>' + dot(j.x, j.y, '#88FF58', j.city, j.end ? j.x - 18 : j.x + 20, j.end ? j.y - 22 : j.y + 34, j.end ? 'end' : 'start');
