    var bars = weeks.map(function (w, i) { var x = i * bw + 6; return '<rect x="' + x + '" y="' + y(w.in) + '" width="' + (bw / 2 - 6) + '" height="' + (H - 20 - y(w.in)) + '" rx="3" fill="#88FF58" opacity=".85"></rect><rect x="' + (x + bw / 2 - 4) + '" y="' + y(w.out) + '" width="' + (bw / 2 - 6) + '" height="' + (H - 20 - y(w.out)) + '" rx="3" fill="#FF5A5A" opacity=".8"></rect><text x="' + (i * bw + bw / 2) + '" y="' + (H - 5) + '" fill="currentColor" opacity=".6" font-size="10" text-anchor="middle">' + pad(w.a.getDate()) + '.' + pad(w.a.getMonth() + 1) + '</text>'; }).join('');
    var line = weeks.map(function (w, i) { return (i ? 'L' : 'M') + (i * bw + bw / 2) + ' ' + yb(w.bal); }).join(' '), th = yb(FINCFG.prog);
    return '<svg viewBox="0 0 ' + W + ' ' + H + '" style="width:100%;height:auto;display:block;color:var(--fg)" role="img" aria-label="Prognoza przepływów: wpływy, wydatki i saldo">' + bars + (th > 0 && th < H - 20 ? '<line x1="0" x2="' + W + '" y1="' + th + '" y2="' + th + '" stroke="#FF9900" stroke-dasharray="4 4" stroke-width="1.2"></line><text x="' + (W - 2) + '" y="' + (th - 4) + '" fill="#FF9900" font-size="9" text-anchor="end">próg ' + Math.round(FINCFG.prog / 1000) + ' tys.</text>' : '') + '<path d="' + line + '" fill="none" stroke="#FF69B2" stroke-width="2.5"></path>' + weeks.map(function (w, i) { return '<circle cx="' + (i * bw + bw / 2) + '" cy="' + yb(w.bal) + '" r="3.5" fill="' + (w.bal < FINCFG.prog ? '#FF9900' : '#FF69B2') + '"></circle>'; }).join('') + '</svg><div style="display:flex;gap:12px;flex-wrap:wrap;font-size:12px" class="t-muted"><span><i style="display:inline-block;width:10px;height:10px;border-radius:3px;background:#88FF58"></i> wpływy</span><span><i style="display:inline-block;width:10px;height:10px;border-radius:3px;background:#FF5A5A"></i> wydatki</span><span><i style="display:inline-block;width:14px;height:3px;background:#FF69B2;vertical-align:middle"></i> saldo na koniec tygodnia</span></div>';
