  function gwDoc(p, site) { return '<article class="page"><h3 class="dtitle">WARUNKI GWARANCJI</h3><p><b>Przedmiot:</b> ' + esc(p ? p.name : site.prod) + ', ' + esc(site ? site.addr + ', ' + site.city : p.city) + '</p><p><b>Okres gwarancji:</b> 24 miesiące od dnia odbioru' + (site && site.gw ? ' – do ' + plDt(site.gw) : '') + '.</p><p><b>Zakres:</b> konstrukcja stalowa i powłoki malarskie, oświetlenie LED i zasilacze, elementy z tworzyw i folii.</p><p><b>Warunek:</b> przegląd gwarancyjny raz w roku (wykonuje Graffico, termin w portalu), użytkowanie zgodnie z instrukcją.</p><p><b>Wyłączenia:</b> uszkodzenia mechaniczne, akty wandalizmu, siła wyższa (np. wiatr powyżej wartości z obliczeń statycznych).</p><p><b>Zgłoszenia:</b> przez portal klienta (zakładka Odbiór i gwarancja) – reakcja do 24 h, usunięcie usterki do 14 dni.</p><p class="small">Wzór demonstracyjny – treść do uzgodnienia z działem prawnym Graffico.</p></article>'; }
